async ({ workspace: { batch }, shell: { exec } }) => {
  const files = ["src/durable/present.ts","src/durable/index.ts","src/durable/host.ts","src/durable/sections.ts"];
  const r = await batch(files.map(file => ({ kind: "read", file, options: { format: "raw" } })));
  const wc = await exec("wc -l src/durable/*.ts test/durable/*.ts docs/durable.md test/durable/*/* 2>/dev/null; ls test/durable");
  return wc.stdout + r.results.map((x: any, i) => `=== ${files[i]}\n${x.value?.content ?? JSON.stringify(x)}`).join("\n");
}
